// Base64-embedded Tivra mark, used only by the SVG-at-the-edge
// certificate routes (certificate, program-completion-certificate,
// course-completion-certificate). These generate a standalone SVG
// string with no access to next/image or the public/ folder at
// request time, so the logo has to be inlined as a data URI rather
// than referenced by path — this used to be hand-approximated as two
// <polygon> shapes forming a boxy plus/cross, which didn't actually
// match the real mark's diagonal-cut winged-crossbar-plus-stem
// geometry (see public/tivra-logo-no-bg.png). Embedding the real
// asset is the only way to guarantee it's actually correct.
export const CERTIFICATE_LOGO_DATA_URI = 'data:image/png;base64,'
